// #1ccd9e מודל הרשאות בסיסי — משתמש רגיל в интерфейсе: меню и прямые адреса закрытых экранов.
// Кейсы: .qa/tests/permissions-isolation/PI-01..PI-03. Только просмотр, данных не создаётся.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import { ACCOUNT_ADMINS_ONLY, SYSTEM_ADMINS_ONLY } from './test-data';

const ADMIN_ONLY_LINKS = ['משתמשי החברה', 'פרופיל חברה'];

test.describe('הרשאות — תפריט ראשי', () => {
  test.describe('משתמש רגיל', () => {
    test.use({ storageState: authState('user') });

    test('משתמש רגיל לא רואה "משתמשי החברה" ו"פרופיל חברה" בתפריט #1ccd9e @desktop @prod-safe', async ({ page }) => {
      await page.goto('/');
      const nav = page.getByRole('navigation', { name: 'ניווט ראשי' });
      await expect(nav.getByRole('link', { name: 'בית', exact: true })).toBeVisible();
      await expect(nav.getByRole('link', { name: 'הוספת מכרז', exact: true })).toBeVisible();
      for (const name of ADMIN_ONLY_LINKS) {
        await expect(nav.getByRole('link', { name, exact: true })).toHaveCount(0);
      }
      await expect(nav.getByRole('link', { name: 'ניהול מערכת', exact: true })).toHaveCount(0);
    });
  });

  // Контроль: те же пункты у מנהל חשבון есть — проверка выше не пустая.
  test.describe('מנהל חשבון', () => {
    test.use({ storageState: authState('admin') });

    test('מנהל חשבון רואה "משתמשי החברה" ו"פרופיל חברה" בתפריט #1ccd9e @desktop @prod-safe', async ({ page }) => {
      await page.goto('/');
      const nav = page.getByRole('navigation', { name: 'ניווט ראשי' });
      for (const name of ADMIN_ONLY_LINKS) {
        await expect(nav.getByRole('link', { name, exact: true })).toBeVisible();
      }
    });
  });
});

test.describe('הרשאות — כתובות ישירות של משתמש רגיל', () => {
  test.use({ storageState: authState('user') });

  for (const route of ['/users', '/users/invite', '/onboarding']) {
    test(`${route}: משתמש רגיל נחסם "זמין למנהלי חשבון בלבד" #1ccd9e @desktop @prod-safe`, async ({ page }) => {
      await page.goto(route);
      await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toBeVisible();
      // Содержимое экрана не показано.
      await expect(page.getByRole('heading', { name: /^(משתמשי החברה|הזמנת משתמש חדש)$/ })).toHaveCount(0);
      await expect(page.getByRole('heading', { name: /^שלב \d מתוך 4:/ })).toHaveCount(0);
    });
  }

  for (const route of ['/admin', '/admin/sources', '/admin/tenders', '/admin/faults']) {
    test(`${route}: משתמש רגיל נחסם "זמין למנהלי מערכת בלבד" #1ccd9e @desktop @prod-safe`, async ({ page }) => {
      await page.goto(route);
      await expect(page.getByText(SYSTEM_ADMINS_ONLY, { exact: true })).toBeVisible();
      await expect(page.getByText(ACCOUNT_ADMINS_ONLY, { exact: true })).toHaveCount(0);
    });
  }
});
